module salary_damage_calculator ( input clk, input rst_n, input start, input [31:0] L0, R0, L1, R1, L2, R2, L3, R3, output reg [31:0] result, output reg done ); wire [31:0] final_result_wire; always @(*) begin wire [31:0] E0 = (L0 + R0) >> 1; wire [31:0] E1 = (L1 + R1) >> 1; wire [31:0] E2 = (L2 + R2) >> 1; wire [31:0] E3 = (L3 + R3) >> 1; wire [31:0] sum_diff = 0; sum_diff = sum_diff + (E1 - E0); sum_diff = sum_diff + (E2 - E0); sum_diff = sum_diff + (E3 - E0); sum_diff = sum_diff + (E2 - E1); sum_diff = sum_diff + (E3 - E1); sum_diff = sum_diff + (E3 - E2); final_result_wire = sum_diff >> 4; end localparam IDLE = 3'd0, WAIT = 3'd1, DONE = 3'd2; reg [2:0] state_reg; reg [31:0] result_reg; reg [4:0] counter_reg; always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state_reg <= IDLE; result_reg <= 32'd0; counter_reg <= 5'd0; done <= 1'b0; end else begin case(state_reg) IDLE: begin if (start) begin result_reg <= final_result_wire; state_reg <= WAIT; counter_reg <= 18; end else begin state_reg <= IDLE; end end WAIT: begin if (counter_reg > 0) begin counter_reg <= counter_reg - 1; state_reg <= WAIT; end else begin state_reg <= DONE; end end DONE: state_reg <= DONE; endcase done <= (state_reg == DONE); end endmodule